# PARITY PoC step 4: exercise the PDF engine switch through the real Flow action (DxCPQ.documentAutomationController.autoGenerateDocumentRecord, which runs
# sendEmailAutomation in a Queueable). One case per run. Each case leaves an Attachment named '<label> <case>.pdf' on the record.
# Usage: powershell -File docs/experiments/parity-poc/4_switch_cases.ps1 -Label off      (then turn the switch on and run it again with -Label on)
param([string]$Org = 'dxtemplates-scratch-30d', [Parameter(Mandatory = $true)][string]$Label,
      [string]$Account = '001RL00003CoThZYAV', [string]$Opp = '006RL00000VwyMvYAJ', [switch]$AccountOnly)   # record ids of the org; -AccountOnly skips the Opportunity case
$account = $Account; $opp = $Opp
$cases = @(
  @('invoice-A4-portrait', 'Invoice Template', $account, 'A4', 'Portrait'),
  @('grant-A4-portrait', 'Grant Proposal', $account, 'A4', 'Portrait'),
  @('invoice-Letter-landscape', 'Invoice Template', $account, 'Letter', 'Landscape'),
  @('newsletter-A4-portrait', 'Newsletter', $opp, 'A4', 'Portrait'))
if ($AccountOnly) { $cases = $cases | Where-Object { $_[2] -eq $account } }
foreach ($c in $cases) {
  $apex = @"
DxCPQ__Document_Template__c t = [SELECT Id FROM DxCPQ__Document_Template__c WHERE Name = '$($c[1])' LIMIT 1];
DxCPQ.documentAutomationController.recordParameters p = new DxCPQ.documentAutomationController.recordParameters();
p.recordId = '$($c[2])'; p.templateId = t.Id; p.documentName = '$Label $($c[0])'; p.docSize = '$($c[3])'; p.docOrientation = '$($c[4])'; p.multiplePdf = false;
DxCPQ.documentAutomationController.autoGenerateDocumentRecord(new List<DxCPQ.documentAutomationController.recordParameters>{ p });
System.debug('SWITCH queued $Label $($c[0])');
"@
  $file = Join-Path $env:TEMP 'switch_case.apex'; $apex | Set-Content $file
  $out = sf apex run -o $Org -f $file 2>&1 | Out-String
  if ($out -match 'SWITCH queued') { Write-Output "queued $Label $($c[0])" } else { Write-Output "FAILED $Label $($c[0]): $(($out -split "`n" | Select-String 'Exception|rror:' | Select-Object -First 1))" }
}
